function RadioGroupField({
  legend,
  helpText,
  name,
  options,
  value,
  onChange,
  error,
  required,
  groupRef,
}) {
  const helpId = useId();
  const errorId = useId();

  const describedBy =
    [helpText ? helpId : null, error ? errorId : null]
      .filter(Boolean)
      .join(" ") || undefined;

  return (
    <div className="form-field">
      <fieldset
        ref={groupRef}
        aria-describedby={describedBy}
        aria-invalid={error ? "true" : undefined}
      >
        <legend>
          {legend}
          {required && (
            <span className="required-marker" aria-hidden="true">
              {" *"}
            </span>
          )}
        </legend>

        {helpText && (
          <p id={helpId} className="field-help">
            {helpText}
          </p>
        )}

        <div className="options">
          {options.map((opt) => {
            const id = `${name}-${opt.value}`;
            return (
              <label key={opt.value} htmlFor={id} className="option">
                <input
                  id={id}
                  type="radio"
                  name={name}
                  value={opt.value}
                  checked={value === opt.value}
                  onChange={(e) => onChange(e.target.value)}
                  required={required}
                />
                <span className="option-label">{opt.label}</span>
              </label>
            );
          })}
        </div>

        {error && (
          <p id={errorId} className="error-text" role="alert">
            Error: {error}
          </p>
        )}
      </fieldset>
    </div>
  );
}

function NotificationPreferencesForm() {
  const [preference, setPreference] = useState("");
  const [error, setError] = useState("");
  const [status, setStatus] = useState("");
  const groupRef = useRef(null);

  const options = [
    { value: "email", label: "Email" },
    { value: "sms", label: "SMS" },
    { value: "push", label: "Push Notifications" },
  ];

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!preference) {
      setError("Please choose how you'd like to receive notifications.");
      setStatus("");
      const firstRadio = groupRef.current?.querySelector('input[type="radio"]');
      firstRadio?.focus();
      return;
    }
    setError("");
    const chosen = options.find((o) => o.value === preference)?.label;
    setStatus(`Preference saved: ${chosen}.`);
  };

  const handleChange = (val) => {
    setPreference(val);
    if (error) setError("");
  };

  return (
    <form className="card" noValidate onSubmit={handleSubmit}>
      <h1>Notification preferences</h1>
      <p className="subtitle">
        Tell us where to reach you when something needs your attention.
      </p>
      <p className="required-legend" aria-hidden="true">
        <span className="required-marker">*</span> indicates a required field
      </p>

      <RadioGroupField
        legend="How do you prefer to receive notifications?"
        name="notification-preference"
        options={options}
        value={preference}
        onChange={handleChange}
        error={error}
        required
        groupRef={groupRef}
      />

      <div className="actions">
        <button type="submit" className="btn">
          Save preference
        </button>
      </div>

      <p className="status" role="status" aria-live="polite">
        {status}
      </p>
    </form>
  );
}

function App() {
  return (
    <>
      <a className="skip-link" href="#main">
        Skip to main content
      </a>
      <div className="page">
        <main id="main">
          <NotificationPreferencesForm />
        </main>
      </div>
    </>
  );
}

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(<App />);
